import {PROCESS_VIEWS,PEOPLE_ROLES,GOA_COMPARISON} from './process-data.js';

const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const values=value=>Array.isArray(value)?value:Object.values(value||{});
const list=value=>Array.isArray(value)?value:value?[value]:[];
export const PROCESS_REDIRECTS={'change-evidence':'configuration-change','occ-incident':'incident-coordination','infrastructure-care':'infrastructure-maintenance','depot-protection':'work-protection'};
export const PROCESS_VARIANTS={'depot-yard/handover':'maintenance-release','depot-yard/dispatch':'maintenance-release','depot-support/planning':'maintenance-release','operations-centre/incident':'incident-coordination','operations-centre/handover':'duty-handover','occ-workplace/handover':'duty-handover'};
export const PROCESS_COMPONENTS={
  'change-item':'configuration-change','change-baseline':'configuration-change','change-requirement':'configuration-change','change-interface':'configuration-change','change-test':'configuration-change','change-issues':'configuration-change','change-acceptance':'asset-handover',
  'occ-incident-coordination':'incident-coordination','occ-alarm-acknowledgement':'incident-coordination','occ-duty-handover':'duty-handover',
  'depot-maintenance-release':'maintenance-release','depot-work-planning':'maintenance-release',
  'depot-work-handover':'maintenance-release','depot-dispatch':'maintenance-release','depot-personnel-protection':'work-protection','depot-energy-isolation':'work-protection',
  'route-inspection':'infrastructure-maintenance','route-work-boundary':'infrastructure-maintenance','route-record':'infrastructure-maintenance',
};
export function processFor(view,component,variant){return PROCESS_VARIANTS[`${view}/${variant}`]||PROCESS_COMPONENTS[component]||PROCESS_REDIRECTS[view]||null;}
export function processStepFor(view,variant){return view==='infrastructure-care'?({inspect:'observe',work:'plan',complete:'record',check:'review'}[variant]||'observe'):view==='depot-protection'?(variant==='indication'?'indication':'boundary'):view==='depot-yard'?(variant==='dispatch'?'allocate':'need'):'';}
export function roleRecords(){return values(PEOPLE_ROLES);}
export function processRecords(){return Object.entries(PROCESS_VIEWS).map(([id,p])=>({id,...p}));}
function roleLabel(id){return roleRecords().find(r=>r.id===id)?.label||roleRecords().find(r=>r.id===id)?.title||id;}
const paragraphs=value=>list(value).map(p=>`<p>${esc(typeof p==='object'?p.text||p.description||p.label:p)}</p>`).join('');
const tokens=value=>list(value).map(x=>esc(typeof x==='object'?x.label||x.title||x.description:x)).join(' · ');

// Every stage remains readable without animation. Selecting a stage reveals
// evidence and responsibility; it never changes an approval or operating state.
export function renderProcessPage(host,state,{sourceChips,parts}){
  const all=processRecords(),p=PROCESS_VIEWS[state.processId]||PROCESS_VIEWS[all[0].id];
  state.processId=p.id||all.find(x=>x.title===p.title)?.id||all[0].id;
  const steps=p.steps||[],selected=steps.find(s=>s.id===state.processStep)||steps[0];
  state.processStep=selected?.id||'';
  const parallel=p.diagramType==='parallel',rows=Math.ceil(steps.length/3),height=parallel?565:rows*154+55;
  let positions=new Map(steps.map((s,i)=>{const row=Math.floor(i/3),col=row%2?2-i%3:i%3;return [s.id,{x:40+col*320,y:30+row*154,w:280,h:98}];}));
  if(parallel)positions=new Map([['report',{x:40,y:25,w:280,h:98}],['context',{x:360,y:25,w:280,h:98}],['operational',{x:40,y:225,w:280,h:98}],['passengers',{x:360,y:225,w:280,h:98}],['technical',{x:680,y:225,w:280,h:98}],['review',{x:360,y:425,w:280,h:98}]]);
  const edges=p.edges||steps.slice(1).map((s,i)=>({from:steps[i].id,to:s.id,label:'Continue'}));
  const diagramEdges=edges.map((edge,i)=>{
    const a=positions.get(edge.from),b=positions.get(edge.to);if(!a||!b)return '';
    const backward=edge.kind==='rework';
    let path,labelX,labelY;
    if(backward){if(a.y===b.y){const above=a.y<150,lane=above?a.y-18:a.y+a.h+25,start=above?a.y:a.y+a.h,end=above?b.y:b.y+b.h;path=`M ${a.x+a.w/2} ${start} V ${lane} H ${b.x+b.w/2} V ${end}`;labelX=(a.x+b.x+a.w)/2;labelY=lane;}else{const lane=985;path=`M ${a.x+a.w} ${a.y+a.h/2} H ${lane} V ${b.y+b.h/2} H ${b.x+b.w}`;labelX=lane;labelY=(a.y+b.y+a.h)/2;}}
    else if(a.y===b.y){const right=b.x>a.x;const x1=right?a.x+a.w:a.x,x2=right?b.x:b.x+b.w;path=`M ${x1} ${a.y+49} H ${x2}`;labelX=(x1+x2)/2;labelY=a.y+30;}
    else{const lane=(a.y+a.h+b.y)/2;path=`M ${a.x+a.w/2} ${a.y+a.h} V ${lane} H ${b.x+b.w/2} V ${b.y-5}`;labelX=b.x+b.w/2;labelY=lane;}
    return `<path d="${path}" class="${backward?'return-edge':''}" marker-end="url(#process-arrow)"/><circle cx="${labelX}" cy="${labelY}" r="10" class="edge-number-circle"/><text x="${labelX}" y="${labelY+4}" class="edge-number">${i+1}</text>`;
  }).join('');
  const stageButtons=steps.map((s,i)=>{const at=positions.get(s.id);return `<button data-process-step="${esc(s.id)}" data-stage-kind="${parallel&&['operational','passengers','technical'].includes(s.id)?'parallel':'stage'}" class="process-stage ${s.id===selected?.id?'active':''}" aria-pressed="${s.id===selected?.id}" style="left:${at.x/10}%;top:${at.y/height*100}%;width:${at.w/10}%;height:${at.h/height*100}%"><span class="stage-order">${String(i+1).padStart(2,'0')}</span><strong>${esc(s.title)}</strong><small>${esc(roleLabel(s.owner))}</small></button>`;}).join('');
  const roleButtons=ids=>list(ids).map(id=>`<button data-role="${esc(id)}">${esc(roleLabel(id))}</button>`).join('');
  host.innerHTML=`<div class="process-shell"><aside class="process-navigation"><p class="eyebrow">People & processes</p><button data-people="all" class="people-index-link">Who does what →</button><details class="process-menu" ${typeof matchMedia==='undefined'||!matchMedia('(max-width:740px)').matches?'open':''}><summary>Browse ${all.length} processes</summary><nav aria-label="Railway processes">${all.map(x=>`<button data-process="${x.id}" ${x.id===state.processId?'aria-current="page"':''}>${esc(x.title)}</button>`).join('')}</nav></details><p>Explore responsibilities and evidence separately from the equipment they concern.</p></aside><article class="process-content"><header><p class="eyebrow">Railway practice / Process study</p><h1>${esc(p.title)}</h1><p class="process-lead">${esc(p.summary)}</p></header><p class="diagram-instruction">Select a stage to see the people, inputs and evidence. <span class="desktop-diagram-help">Dashed arrows return to an unresolved question.</span><span class="mobile-diagram-help">Read the connections below for parallel work and return paths.</span></p><div class="process-diagram" style="aspect-ratio:1000/${height}"><svg viewBox="0 0 1000 ${height}" aria-hidden="true"><defs><marker id="process-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z"/></marker></defs>${diagramEdges}</svg>${stageButtons}</div><details class="process-connections"><summary>Handoffs, parallel work and return paths</summary><ol>${edges.map((e,i)=>`<li><span>${i+1}</span><strong>${esc(steps.find(s=>s.id===e.from)?.title)} → ${esc(steps.find(s=>s.id===e.to)?.title)}</strong><p>${esc(e.label)}${e.kind==='parallel'?' · Runs alongside the other coordination branches.':e.kind==='rework'?' · Return path; retain the open condition.':''}</p></li>`).join('')}</ol></details><section class="process-detail" aria-live="polite"><p class="eyebrow">Stage ${steps.indexOf(selected)+1} / ${steps.length}</p><h2>${esc(selected?.title)}</h2><div class="process-ownership"><span>Responsible role</span>${roleButtons(selected?.owner)}${selected?.ownerContext?`<small>${esc(selected.ownerContext)}</small>`:''}<span>Contributors</span>${roleButtons(selected?.participants)}</div><div class="evidence-columns"><section><h3>Inputs</h3>${paragraphs(selected?.inputs)}</section><section><h3>Work at this stage</h3>${paragraphs(selected?.action)}</section><section><h3>Outputs & evidence</h3>${paragraphs(selected?.outputs)}</section></div><div class="process-check"><h3>Before progressing</h3>${paragraphs(selected?.check)}</div>${list(selected?.links).length?`<div class="process-equipment"><h3>Connected equipment & concepts</h3>${list(selected.links).filter(id=>parts.has(id)).map(id=>`<button ${PROCESS_COMPONENTS[id]?`data-reference="${esc(id)}"`:`data-explore-component="${esc(id)}"`}>${esc(parts.get(id).label)} ↗</button>`).join('')}</div>`:''}${sourceChips(selected?.sources||p.sources||[])}</section>${p.branches?.length?`<section class="process-branches"><h2>When the path changes</h2>${p.branches.map(b=>`<p><strong>${esc(b.when||b.label||b.condition||b.title)}</strong> ${esc(b.outcome||b.description||b.action||b.text)}</p>`).join('')}</section>`:''}<div class="process-limits"><h2>How to read this study</h2>${paragraphs(p.limits)}<p>Stages show relationships, not a prescribed railway procedure. Titles and accountabilities vary by organisation. A diagram selection is not an authorization to work, accept an asset or run a train.</p>${sourceChips(p.sources||[])}</div><button data-people="all" class="text-link">Meet the roles across the railway →</button></article></div>`;
}

export function renderPeoplePage(host,state,{sourceChips}){
  const roles=roleRecords(),role=roles.find(r=>r.id===state.roleId)||roles[0];state.roleId=role?.id;
  const responsibilities=role?.responsibilities||role?.does||role?.tasks;
  const interfaces=role?.interfaces||role?.worksWith||role?.collaborates;
  const goa=values(GOA_COMPARISON.grades||GOA_COMPARISON.rows||GOA_COMPARISON.levels||GOA_COMPARISON);
  host.innerHTML=`<div class="people-page"><header><p class="eyebrow">People & processes</p><h1>People make the railway work</h1><p class="process-lead">Equipment supports responsibilities. Meet representative roles in service, the control centre, stations and maintenance, then follow the decisions and evidence that connect them.</p></header><div class="people-layout"><nav aria-label="Railway roles">${roles.map(r=>`<button data-role="${esc(r.id)}" aria-pressed="${r.id===role?.id}">${esc(r.label||r.title)}</button>`).join('')}</nav><section class="role-detail"><p class="eyebrow">${esc(role?.location||role?.area||'Representative role')}</p><h2>${esc(role?.label||role?.title)}</h2>${paragraphs(role?.summary||role?.purpose)}<h3>Responsibilities</h3>${paragraphs(responsibilities)}${role?.receives?`<h3>Receives</h3>${paragraphs(role.receives)}<h3>Produces</h3>${paragraphs(role.produces)}`:''}${interfaces?`<h3>Works with</h3>${paragraphs(interfaces)}`:''}${role?.boundary||role?.limits?`<h3>Responsibility boundary</h3>${paragraphs(role.boundary||role.limits)}`:''}${sourceChips(role?.sources||[])}${list(role?.processes).length?`<div class="role-processes">${list(role.processes).filter(id=>PROCESS_VIEWS[id]).map(id=>`<button data-process="${esc(id)}">${esc(PROCESS_VIEWS[id].title)} →</button>`).join('')}</div>`:''}</section></div><section class="goa-section"><h2>Automation changes the allocation of work</h2><p>Grade of automation concerns operating responsibilities. It is separate from whether a railway uses conventional signalling, CBTC or a particular supplier.</p><div class="table-scroll"><table><caption>Representative roles of people and automation</caption><thead><tr><th>Grade</th><th>Train operation</th><th>People & response</th></tr></thead><tbody>${goa.filter(g=>typeof g==='object').map(g=>`<tr><th>${esc(g.label||g.grade||g.id)}</th><td>${esc(g.operation||g.trainOperation||g.description||g.summary||'')}${g.driving?`<p>${esc(g.driving)}</p>`:''}</td><td>${tokens(g.onboardOperatingRole||g.people||g.staffing||g.responsibilities||g.humanRole)}${g.response?`<p>${esc(g.response)}</p>`:''}</td></tr>`).join('')}</tbody></table></div><p>GoA4 does not require an onboard driver for normal operation. It does not establish a universal reduction in station attendants: passenger assistance, disruption, evacuation, security and degraded operation still need an explicit operating concept and competent people.</p>${sourceChips(GOA_COMPARISON.sources||[])}</section><section class="process-directory"><h2>Follow a process</h2>${processRecords().map(p=>`<button data-process="${p.id}"><strong>${esc(p.title)}</strong><span>${esc(p.summary)}</span></button>`).join('')}</section></div>`;
}
